import java.util.Scanner;

public class Main {
    static final int MAXN = 32;
    static final int MOD = 1000000007;

    static class Matrix {
        int N;
        int[][] a = new int[MAXN][MAXN];

        void initialize(int _N, int _V) {
            N = _N;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    a[i][j] = _V;
                }
            }
        }

        void multiply_with(Matrix b) {
            int[][] temp = new int[N][N];
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    long t = 0;
                    for (int k = 0; k < N; k++) {
                        t += (long) a[i][k] * b.a[k][j];
                    }
                    temp[i][j] = (int) (t % MOD);
                }
            }
            for (int i = 0; i < N; i++) {
                System.arraycopy(temp[i], 0, a[i], 0, N);
            }
        }
    }

    static Matrix[][] A = new Matrix[64][32];
    static Matrix[][] prefix = new Matrix[64][32];
    static Matrix[][] suffix = new Matrix[64][32];

    static long n;
    static int k;

    static void prepare(int index) {
        prefix[index][1] = A[index][0];
        for (int j = 2; j <= k; j++) {
            prefix[index][j] = new Matrix();
            prefix[index][j].initialize(k + 1, 0);
            for (int x = 0; x < prefix[index][j - 1].N; x++) {
                for (int y = 0; y < prefix[index][j - 1].N; y++) {
                    prefix[index][j].a[x][y] = prefix[index][j - 1].a[x][y];
                }
            }
            prefix[index][j].multiply_with(A[index][j - 1]);
        }
        suffix[index][k - 1] = A[index][k - 1];
        for (int j = k - 2; j >= 0; j--) {
            suffix[index][j] = new Matrix();
            suffix[index][j].initialize(k + 1, 0);
            for (int x = 0; x < suffix[index][j + 1].N; x++) {
                for (int y = 0; y < suffix[index][j + 1].N; y++) {
                    suffix[index][j].a[x][y] = suffix[index][j + 1].a[x][y];
                }
            }
            suffix[index][j].multiply_with(suffix[index][j + 1]);
        }
    }

    static int sum_of_digits(long num) {
        int s = 0;
        while (num > 0) {
            s = (s + (int) (num % k)) % k;
            num /= k;
        }
        return s;
    }

    static Matrix compute_matrix(long num, int m) {
        if (num < k) {
            Matrix res = new Matrix();
            res.initialize(k + 1, 0);
            for (int i = 0; i < res.N; i++) {
                for (int j = 0; j < res.N; j++) {
                    res.a[i][j] = A[m][0].a[i][j];
                }
            }
            for (int i = 1; i < num; i++) {
                res.multiply_with(A[m][i]);
            }
            return res;
        }
        Matrix res = compute_matrix(num / k, m + 1);
        int x = sum_of_digits(num / k);
        for (int i = 0; i < num % k; i++) {
            res.multiply_with(A[m][(x + i) % k]);
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextInt();

        for (int i = 0; i < k; i++) {
            for (int m = 0; m < 64; m++) {
                A[m][i] = new Matrix();
                A[m][i].initialize(k + 1, 0);
                for (int j = 0; j <= k; j++) {
                    A[m][i].a[j][j] = 1;
                    A[m][i].a[j][i] = 1;
                }
            }
        }

        int m = 1;
        while (pow(k, m) - 1000 <= n) {
            prepare(m - 1);
            for (int x = 0; x < k; x++) {
                A[m][x] = new Matrix();
                A[m][x].initialize(k + 1, 0);
                for (int i = 0; i < A[m - 1][x].N; i++) {
                    for (int j = 0; j < A[m - 1][x].N; j++) {
                        A[m][x].a[i][j] = suffix[m - 1][x].a[i][j];
                    }
                }
                if (x > 0) {
                    A[m][x].multiply_with(prefix[m - 1][x]);
                }
            }
            m++;
        }

        Matrix finalMatrix = compute_matrix(n, 0);
        int total = 0;
        for (int i = 0; i <= k; i++) {
            total = (total + finalMatrix.a[k][i]) % MOD;
        }
        System.out.println(total);
        sc.close();
    }

    static long pow(long base, int exp) {
        long result = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b);
            }
            b = (b * b);
            e >>= 1;
        }
        return result;
    }
}
